<?php
namespace Sis_medico\Services;use Illuminate\Support\Facades\Auth;use Sis_medico\Support\RequestSchema as Schema;use Sis_medico\ClinicalEncounter;use Sis_medico\ClinicalSafetyEvent;use Sis_medico\ClinicalSafetyEventLog;use Sis_medico\Exceptions\ClinicalSafetyEventException;
class ClinicalSafetyEventService
{
 const OPEN='OPEN',REVIEW='UNDER_REVIEW',MITIGATED='MITIGATED',ESCALATED='ESCALATED',CLOSED='CLOSED';
 public function available(){return Schema::hasTable('clinical_safety_events')&&Schema::hasTable('clinical_safety_event_logs');}
 public function create(array $data,array $context=array()){$errors=$this->validateData($data);if(count($errors))throw new ClinicalSafetyEventException(implode(' ',$errors));$enc=ClinicalEncounter::find($data['encounter_id']);if(!$enc)throw new ClinicalSafetyEventException('No se encontró el episodio clínico.');$actor=$this->actor($context);$severe=in_array($data['severity'],array('HIGH','CRITICAL'),true);$event=ClinicalSafetyEvent::create(array('encounter_id'=>$enc->id,'patient_id'=>$enc->id_paciente,'category'=>$data['category'],'subtype'=>$this->value($data,'subtype'),'severity'=>$data['severity'],'occurred_at'=>$data['occurred_at'],'detected_at'=>date('Y-m-d H:i:s'),'location'=>trim($data['location']),'description'=>trim($data['description']),'immediate_actions'=>trim($data['immediate_actions']),'isolation_type'=>$this->value($data,'isolation_type'),'pathogen'=>$this->value($data,'pathogen'),'custody_reference'=>$this->value($data,'custody_reference'),'status'=>self::OPEN,'assigned_to'=>$data['assigned_to'],'notification_required'=>$severe?1:0,'review_due_at'=>$severe?date('Y-m-d H:i:s',time()+3600):date('Y-m-d H:i:s',time()+86400),'created_by'=>$actor,'ip_address'=>$this->ip($context)));$this->log($event,'CREATED',null,self::OPEN,'Evento de seguridad registrado.',$context);if(app(ClinicalRecordService::class)->available())app(ClinicalRecordService::class)->registerDocument($enc->id,$enc->id_paciente,'CLINICAL_SAFETY_EVENT','clinical_safety_event',$event->id,array('title'=>$event->category,'content'=>$event->description.'|'.$event->immediate_actions),$context);return $event;}
 public function notify(ClinicalSafetyEvent $event,$recipient,array $context=array()){$recipient=trim($recipient);if(strlen($recipient)<3)throw new ClinicalSafetyEventException('Registre el receptor de la notificación.');return ClinicalSafetyEventGuard::run(function()use($event,$recipient,$context){$event->notified_at=date('Y-m-d H:i:s');$event->notified_by=$this->actor($context);$event->notification_recipient=$recipient;$event->save();$this->log($event,'NOTIFIED',$event->status,$event->status,'Receptor: '.$recipient,$context);return $event;});}
 public function transition(ClinicalSafetyEvent $event,$to,array $data,array $context=array()){$allowed=array(self::OPEN=>array(self::REVIEW,self::MITIGATED,self::ESCALATED),self::ESCALATED=>array(self::REVIEW,self::MITIGATED),self::REVIEW=>array(self::MITIGATED,self::CLOSED),self::MITIGATED=>array(self::REVIEW,self::CLOSED));if(!isset($allowed[$event->status])||!in_array($to,$allowed[$event->status],true))throw new ClinicalSafetyEventException('Transición de seguridad no permitida.');return ClinicalSafetyEventGuard::run(function()use($event,$to,$data,$context){if($to===self::CLOSED){if($event->notification_required&&!$event->notified_at)throw new ClinicalSafetyEventException('No puede cerrar un evento grave sin notificación registrada.');if(strlen(trim($this->value($data,'root_cause')))<10||strlen(trim($this->value($data,'corrective_actions')))<10)throw new ClinicalSafetyEventException('Documente causa raíz y acciones correctivas antes del cierre.');$event->root_cause=trim($data['root_cause']);$event->corrective_actions=trim($data['corrective_actions']);$event->closed_at=date('Y-m-d H:i:s');$event->closed_by=$this->actor($context);}$from=$event->status;$event->status=$to;$event->save();$this->log($event,'STATUS_CHANGED',$from,$to,$this->value($data,'notes'),$context);return $event;});}
 public function escalateOverdue(){$now=date('Y-m-d H:i:s');$count=0;ClinicalSafetyEvent::whereIn('status',array(self::OPEN,self::REVIEW))->where('review_due_at','<',$now)->chunk(100,function($rows)use(&$count){foreach($rows as $event){ClinicalSafetyEventGuard::run(function()use($event,&$count){$from=$event->status;$event->status=self::ESCALATED;$event->save();$this->log($event,'SLA_ESCALATED',$from,self::ESCALATED,'Plazo de revisión vencido.',array('actor_id'=>'SYSTEM'));$count++;});}});return $count;}
 public function integrity(){if(!$this->available())return array('available'=>false,'pending'=>null);$now=date('Y-m-d H:i:s');$overdue=ClinicalSafetyEvent::whereIn('status',array(self::OPEN,self::REVIEW))->where('review_due_at','<',$now)->count();$unnotified=ClinicalSafetyEvent::where('notification_required',1)->whereNull('notified_at')->where('review_due_at','<',$now)->count();$withoutLog=ClinicalSafetyEvent::whereDoesntHave('logs')->count();$invalidClosed=ClinicalSafetyEvent::where('status',self::CLOSED)->where(function($q){$q->whereNull('closed_at')->orWhereNull('closed_by')->orWhereNull('root_cause')->orWhereNull('corrective_actions')->orWhere(function($n){$n->where('notification_required',1)->whereNull('notified_at');});})->count();$orphan=ClinicalSafetyEvent::whereDoesntHave('encounter')->count();$invalidContext=ClinicalSafetyEvent::whereHas('encounter',function($q){$q->whereRaw('clinical_safety_events.patient_id <> clinical_encounters.id_paciente');})->count();$orphanLogs=\Sis_medico\ClinicalSafetyEventLog::whereDoesntHave('event')->count();$missingNotificationLog=ClinicalSafetyEvent::whereNotNull('notified_at')->whereDoesntHave('logs',function($q){$q->where('event_type','NOTIFIED');})->count();$missingClosureLog=ClinicalSafetyEvent::where('status',self::CLOSED)->whereDoesntHave('logs',function($q){$q->where('event_type','STATUS_CHANGED')->where('to_status',self::CLOSED);})->count();$pending=$overdue+$unnotified+$withoutLog+$invalidClosed+$orphan+$invalidContext+$orphanLogs+$missingNotificationLog+$missingClosureLog;return array('available'=>true,'pending'=>$pending,'overdue'=>$overdue,'unnotified'=>$unnotified,'without_log'=>$withoutLog,'invalid_closed'=>$invalidClosed,'orphan'=>$orphan,'invalid_context'=>$invalidContext,'orphan_logs'=>$orphanLogs,'missing_notification_log'=>$missingNotificationLog,'missing_closure_log'=>$missingClosureLog);}
 private function validateData(array $d){$e=array();if(!in_array($this->value($d,'category'),array('ADVERSE_EVENT','HAI','ISOLATION','CUSTODY'),true))$e[]='Seleccione una categoría de seguridad válida.';if(!in_array($this->value($d,'severity'),array('LOW','MODERATE','HIGH','CRITICAL'),true))$e[]='Seleccione la severidad.';foreach(array('encounter_id'=>'episodio','occurred_at'=>'fecha del evento','location'=>'ubicación','assigned_to'=>'responsable') as $k=>$v)if(trim($this->value($d,$k))==='')$e[]='Complete '.$v.'.';if(strlen(trim($this->value($d,'description')))<10)$e[]='Describa el evento clínico.';if(strlen(trim($this->value($d,'immediate_actions')))<5)$e[]='Registre las acciones inmediatas.';if($this->value($d,'category')==='HAI'&&trim($this->value($d,'pathogen'))==='')$e[]='Registre el agente confirmado o sospechoso de IAAS.';if($this->value($d,'category')==='ISOLATION'&&trim($this->value($d,'isolation_type'))==='')$e[]='Registre el tipo de aislamiento.';if($this->value($d,'category')==='CUSTODY'&&trim($this->value($d,'custody_reference'))==='')$e[]='Registre la referencia de custodia.';return $e;}
 private function log($event,$type,$from,$to,$detail,array $context){ClinicalSafetyEventLog::create(array('clinical_safety_event_id'=>$event->id,'event_type'=>$type,'from_status'=>$from,'to_status'=>$to,'detail'=>$detail,'actor_id'=>$this->actor($context),'ip_address'=>$this->ip($context)));}private function value(array $d,$k){return isset($d[$k])?$d[$k]:null;}private function actor(array $c){return isset($c['actor_id'])?$c['actor_id']:(Auth::check()?Auth::user()->id:null);}private function ip(array $c){return isset($c['ip'])?$c['ip']:(isset($_SERVER['REMOTE_ADDR'])?$_SERVER['REMOTE_ADDR']:null);}
}
